var attachRequest = /gira|invi[ao]|allega|mand[ae]|spedi/.test(emailBodyLower);
var attachFileId = null;
var attachFileName = null;
if (attachRequest && validItems.length > 0) {
  var pdfItems = validItems.filter(function(i) { var n = (i.json.name || '').toLowerCase(); return !n.includes('f24') && !n.includes('tel-'); });
  var cedolinoItem = pdfItems.find(function(i) { return (i.json.name || '').toLowerCase().includes('cedolino'); });
