return [{ json: {
  from: String(emailData.from?.value?.[0]?.address || emailData.from || ''),
  to: String(emailData.to?.value?.[0]?.address || emailData.to || ''),
  subject: String(emailData.subject || ''),
  snippet: String(emailData.snippet || ''),
