try {
  var emailData = $('Gmail Trigger1').item.json;
  emailText = emailData.text || emailData.snippet || '';
  emailSubject = emailData.subject || '';
} catch(e) {}
var webSearchTopics = ['AGGIORNAMENTI', 'INPS', 'INAIL', 'PREVIDENZA', 'DIRITTO_LAVORO', 'FISCALE_NORMATIVA', 'FISCALE_USPPIDA'];
var needsWebSearch = webSearchTopics.includes(topic);
var normativeKeywords = ['accertamento', 'circolare', 'normativa', 'decreto', 'aggiornamento', 'sentenza', 'contributi', 'previdenz', 'ricerca normativa', 'verifica'];
var emailLower = (emailText + ' ' + emailSubject).toLowerCase();
if (!needsWebSearch) {
  needsWebSearch = normativeKeywords.some(function(kw) { return emailLower.includes(kw); });
}
var searchQuery = '';
if (needsWebSearch) {
  var keyTerms = [];
  if (emailLower.includes('inps')) keyTerms.push('INPS');
  if (emailLower.includes('inail')) keyTerms.push('INAIL');
  if (emailLower.includes('accertamento')) keyTerms.push('accertamento');
  if (emailLower.includes('circolare')) keyTerms.push('circolare ministeriale');
  if (emailLower.includes('cedolino') || emailLower.includes('paga') || topic === 'PAGHE') keyTerms.push('cedolini busta paga');
  if (emailLower.includes('previdenz') || topic === 'PREVIDENZA') keyTerms.push('previdenza sociale');
  if (emailLower.includes('decreto')) keyTerms.push('decreto legge');
  if (emailLower.includes('contratto') || topic === 'DIRITTO_LAVORO') keyTerms.push('contratto di lavoro CCNL');
  if (topic === 'AGGIORNAMENTI') keyTerms.push('aggiornamenti normativi lavoro');
  if (year) keyTerms.push(year);
  if (keyTerms.length === 0) keyTerms.push('normativa lavoro italiana');
  keyTerms.push('Italia');
  searchQuery = keyTerms.join(' ');
}
return [{ json: { needsWebSearch: needsWebSearch, searchQuery: searchQuery } }];

